 * @param {Function} fn
 * @param {number} t
 * @return {Function}
 */
var throttle = function(fn, t) {
    let timeoutId = null;
    let nextArgs = null;

    const helper = () => {
        if (nextArgs) {
            fn(...nextArgs);
            nextArgs = null;
            timeoutId = setTimeout(helper, t);
        } else {
            timeoutId = null;
        }
    };

    return function(...args) {
        if (!timeoutId) {
            fn(...args);
            timeoutId = setTimeout(helper, t);
        } else {
            nextArgs = args;
        }
    };
};
