type F = (...args: any[]) => void;

function throttle(fn: F, t: number): F {
    let timeoutId: any = null;
    let nextArgs: any[] | null = null;

    const helper = () => {
        if (nextArgs) {
            fn(...nextArgs);
            nextArgs = null;
            timeoutId = setTimeout(helper, t);
        } else {
            timeoutId = null;
        }
    };

    return function(...args: any[]) {
        if (!timeoutId) {
            fn(...args);
            timeoutId = setTimeout(helper, t);
        } else {
            nextArgs = args;
        }
    };
}
